    <main class="ps-main">
        <header class="ps-top"><div class="ps-heading"><div class="ps-identity"><a :href="boot.list_url"><h1><span class="ps-panel-name" x-text="boot.panel_name || 'Pelican'"></span> <span class="ps-title-pelican">× Pelican</span></h1></a><small>Enhanced by <a class="ps-project-link" href="https://github.com/jerajerajerajera/PelicanSimplify" target="_blank" rel="noopener noreferrer">Simplify</a></small></div><a x-show="server" :href="boot.list_url" class="ps-back-overview" aria-label="Back to server overview"><svg aria-hidden="true"><use href="#ps-back"/></svg><span>Back to server overview</span></a></div><nav class="ps-top-actions" aria-label="Panel navigation" :class="{'nav-open':navMenu}" x-on:click.outside="navMenu=false;accountMenu=false" x-on:keydown.escape.stop="navMenu=false;accountMenu=false"><button type="button" class="ps-icon-button subtle ps-mobile-menu" aria-label="Panel navigation" aria-controls="ps-navigation-items" :aria-expanded="navMenu" x-on:click="navMenu=!navMenu;accountMenu=false;appearanceMenu=false"><svg aria-hidden="true"><use href="#ps-menu"/></svg></button><div class="ps-nav-items" id="ps-navigation-items">@if(\Simplify\Panel\Services\Extensions::web()) @include('server-directory::simplify.navigation') @endif<a x-show="boot.admin_url" :href="server?.admin_server_url || boot.admin_url" class="ps-icon-button subtle" title="Legacy panel" aria-label="Legacy panel"><svg aria-hidden="true"><use href="#ps-legacy"/></svg><span class="ps-mobile-label">Legacy panel</span></a><button type="button" x-show="boot.settings_url" x-on:click="openPanelSettings()" class="ps-icon-button subtle" title="Simplify settings" aria-label="Simplify settings" aria-haspopup="dialog"><svg aria-hidden="true"><use href="#ps-gear"/></svg><span class="ps-mobile-label">Simplify settings</span></button><div class="ps-overview-appearance" x-on:click.outside="appearanceMenu=false" x-on:keydown.escape.stop="appearanceMenu=false;$refs.overviewAppearance.focus()"><button type="button" x-ref="overviewAppearance" class="ps-icon-button subtle" title="Customize appearance" aria-label="Customize appearance" aria-controls="ps-overview-appearance-menu" :aria-expanded="appearanceMenu" x-on:click="appearanceMenu=!appearanceMenu;accountMenu=false"><svg aria-hidden="true"><use href="#ps-wand"/></svg><span class="ps-mobile-label">Customize appearance</span></button><div id="ps-overview-appearance-menu" class="ps-overview-appearance-menu" x-show="appearanceMenu" x-cloak x-transition.opacity><strong>Customize appearance</strong><div class="ps-appearance-section"><span>Theme</span><div class="ps-appearance-choice" role="group" aria-label="Colour theme"><template x-for="t in ['light','dark','system']" :key="t"><button x-on:click="setTheme(t)" :class="{'selected':theme===t}" :title="t==='light'?'Light theme':t==='dark'?'Dark theme':'System theme'" :aria-label="t+' theme'" :aria-pressed="theme===t"><svg aria-hidden="true"><use :href="t==='light'?'#ps-sun':t==='dark'?'#ps-moon':'#ps-monitor'"/></svg><span x-text="t==='light'?'Light':t==='dark'?'Dark':'System'"></span></button></template></div></div><div x-show="!server"><div class="ps-appearance-section" x-show="!overviewCompact"><span>Layout</span><div class="ps-appearance-choice" role="group" aria-label="Overview layout"><template x-for="view in [{key:'grid',label:'Grid',icon:'grid'},{key:'list',label:'List',icon:'list'}]" :key="view.key"><button type="button" :class="{'selected':overviewView===view.key}" :aria-pressed="overviewView===view.key" x-on:click="setOverviewView(view.key)"><svg aria-hidden="true"><use :href="'#ps-'+view.icon"/></svg><span x-text="view.label"></span></button></template></div></div><div class="ps-appearance-section"><span>Large icon</span><div class="ps-appearance-choice" role="group" aria-label="Large overview icon"><button type="button" :class="{'selected':overviewPreferences.largeIcon==='server'}" :aria-pressed="overviewPreferences.largeIcon==='server'" x-on:click="setOverviewPreference('largeIcon','server')">Server icon</button><button type="button" :class="{'selected':overviewPreferences.largeIcon==='egg'}" :aria-pressed="overviewPreferences.largeIcon==='egg'" x-on:click="setOverviewPreference('largeIcon','egg')">Egg icon</button></div></div><div class="ps-appearance-section"><span>Server details</span><template x-for="option in [{key:'showMotd',label:'Minecraft MOTD'},{key:'showCpu',label:'CPU tile'},{key:'showRam',label:'RAM tile'},{key:'showQuickActions',label:'Show quick actions on server overview'}]" :key="option.key"><button type="button" class="ps-appearance-toggle" role="switch" :aria-checked="overviewPreferences[option.key]" x-on:click="setOverviewPreference(option.key,!overviewPreferences[option.key])"><span x-text="option.label"></span><span class="ps-appearance-switch" :class="{'on':overviewPreferences[option.key]}" aria-hidden="true"><i></i></span></button></template></div></div></div></div><div class="ps-account" x-on:click.outside="accountMenu=false" x-on:keydown.escape.stop="accountMenu=false"><button x-on:click="accountMenu=!accountMenu" class="ps-icon-button ps-account-button" :class="{'has-avatar':!!boot.avatar}" title="Account" aria-label="Account menu" aria-haspopup="true" :aria-expanded="accountMenu"><span class="ps-account-avatar" x-data="{failed:false}"><img x-show="boot.avatar && !failed" :src="boot.avatar" alt="" x-on:error="failed=true"><svg x-show="!boot.avatar || failed"><use href="#ps-account"/></svg></span><span class="ps-mobile-label">Account</span></button><div class="ps-account-menu" x-show="accountMenu" x-cloak x-transition><span class="ps-account-name" x-text="boot.user"></span><button type="button" class="ps-profile-button" x-on:click="openAccount()" title="Profile" aria-label="Profile" aria-haspopup="dialog"><svg aria-hidden="true"><use href="#ps-account"/></svg><span>Profile</span></button><form method="post" action="{{ route('filament.app.auth.logout') }}">@csrf<button type="submit" title="Sign out" aria-label="Sign out"><svg><use href="#ps-logout"/></svg></button></form></div></div></div></nav></header>
        <section x-show="!server" class="ps-overview" :class="{'is-list':overviewView==='list'}" :style="{'--grid-columns':overviewColumns()}">
            <div class="ps-server-scroll" tabindex="0" role="region" aria-label="Servers"><div class="ps-server-stage" :class="{'is-list':overviewView==='list'}">            <div class="ps-overview-toolbar" :class="{'is-list':overviewView==='list'}">
                <div class="ps-game-filters" role="group" aria-label="Filter servers by game">
