                    <template x-for="game in gameOptions()" :key="game.key"><button type="button" class="ps-outline-button" :class="{'selected':gameFilter===game.key}" :aria-pressed="gameFilter===game.key" x-on:click="setGameFilter(game.key)" x-text="game.label"></button></template>
                </div>

            </div>
<div class="ps-server-layout"><div class="ps-server-grid" :class="{'is-list':overviewView==='list','has-motd':overviewPreferences.showMotd,'no-metrics':!overviewMetrics().length,'no-quick-actions':!overviewPreferences.showQuickActions}"><div class="ps-create-tiles" x-show="boot.can_create"><button type="button" x-show="canCreateGame('minecraft')" x-on:click="openCreate('minecraft')" class="ps-server-card ps-create-card is-minecraft" aria-label="Create Minecraft server" aria-haspopup="dialog"><span class="ps-create-plus"><svg aria-hidden="true"><use href="#ps-creeper"/></svg><span class="ps-create-add"><svg aria-hidden="true"><use href="#ps-plus"/></svg></span></span><h3><span>Create</span><strong>Minecraft</strong><span>server</span></h3></button><button type="button" :disabled="!canCreateGame('other')" x-on:click="openCreate('other')" class="ps-server-card ps-create-card is-other" aria-label="Create other game server with legacy creator" aria-haspopup="dialog"><span class="ps-create-plus"><svg aria-hidden="true"><use href="#ps-gamepad"/></svg><span class="ps-create-add"><svg aria-hidden="true"><use href="#ps-plus"/></svg></span></span><h3><span>Create</span><strong>Other game</strong><span>server</span></h3></button></div><template x-for="s in visibleServers()" :key="s.uuid"><div class="ps-server-entry" :class="{'has-card-motd':overviewPreferences.showMotd &amp;&amp; s.game==='minecraft' &amp;&amp; !!s.motd,'has-power':overviewPreferences.showQuickActions &amp;&amp; s.linked && Object.values(s.permissions || {}).some(Boolean),'confirming-power':powerConfirmation?.uuid===s.uuid}" :style="accentStyle(s.uuid)"><article class="ps-server-card" :class="{'locked':!s.linked}" :style="accentStyle(s.uuid)"><span class="ps-offline-artwork" x-show="s.status==='offline'" aria-label="Server offline"><svg><use href="#ps-offline"/></svg></span><img class="ps-card-background" x-show="s.background && s.status!=='offline'" :src="safeImage(s.background)" alt="" x-on:error="$el.style.visibility='hidden'"><button class="ps-server-open" x-on:click="s.linked && (location.href=s.url)" :disabled="!s.linked" :aria-label="s.linked?'Open '+s.name:s.name+' — not assigned to you'"><div class="ps-card-head"><span class="ps-card-icons" :class="{'egg-primary':overviewPreferences.largeIcon==='egg' &amp;&amp; !!(s.egg_icon || s.software_icon)}"><span class="ps-card-icon" title="Server icon"><img x-show="s.server_icon || s.icon" :src="safeImage(s.server_icon || s.icon)" alt="Server icon" x-on:load="$el.style.visibility=''" x-on:error="$el.style.visibility='hidden'"><svg x-show="!s.server_icon && !s.icon"><use href="#ps-cube"/></svg></span><span class="ps-card-egg-icon" x-show="s.egg_icon || s.software_icon" :aria-label="softwareTooltip(s)" x-on:mouseenter="showSoftwareTooltip(s,$el)" x-on:mouseleave="softwareHint=null"><img :src="safeImage(s.egg_icon || s.software_icon)" alt="Server software icon" x-on:load="$el.style.visibility=''" x-on:error="$el.style.visibility='hidden'"></span></span></div><div class="ps-card-title"><div class="ps-card-title-row" x-data="{observer:null,width:0,init(){this.observer=new ResizeObserver(()=>{const w=this.$el.clientWidth;if(w!==this.width){this.width=w;this.fitCardTitle(this.$el,s.alias||s.name)}});this.observer.observe(this.$el)},destroy(){this.observer?.disconnect()}}" x-effect="const name=s.alias||s.name;$nextTick(()=>fitCardTitle($el,name))"><h3 x-text="s.alias || s.name"></h3><small class="ps-card-real-name" :class="{'no-alias':!s.alias}" x-text="s.alias ? '('+s.name+')' : '\u00a0'"></small></div><div class="ps-card-motd ps-motd-preview ps-motd-display" x-show="overviewPreferences.showMotd &amp;&amp; s.game==='minecraft' &amp;&amp; s.motd"><template x-for="(part,index) in motdPreview(s.motd)" :key="index"><span :style="part.style" x-text="part.text"></span></template></div></div><div class="ps-card-usage" x-show="overviewMetrics().length" :class="{'single-metric':overviewMetrics().length===1}"><template x-for="metric in overviewMetrics()" :key="metric.key"><div class="ps-card-mini-metric"><span class="ps-card-usage-label"><span class="ps-card-metric-name"><svg aria-hidden="true"><use :href="'#ps-'+metric.icon"/></svg><span x-text="metric.label"></span></span><strong x-text="metric.key==='cpu'?cpuLabel(s):cardRamLabel(s)"></strong></span><svg class="ps-card-graph" viewBox="0 0 100 30" preserveAspectRatio="none" aria-hidden="true"><path class="ps-card-graph-axis" d="M2 27H98"/><path :d="cardGraph(s,metric.key)"/><circle x-show="cardGraphPoint(s,metric.key)!==null" cx="98" :cy="cardGraphPoint(s,metric.key) || 0" r="1.4"/></svg></div></template></div><div class="ps-card-game ps-card-badges ps-identity-badges"><span class="ps-list-game"><svg aria-hidden="true"><use :href="s.game==='minecraft'?'#ps-cube':'#ps-gamepad'"/></svg><span x-text="s.game_label"></span></span><span class="ps-status" :class="s.status"><i></i><span x-text="s.status"></span></span></div><div class="ps-card-bottom" x-show="overviewView==='grid'"><span x-text="playerCount(s)"></span><svg><use :href="s.linked?'#ps-chevron':'#ps-lock'"/></svg></div></button><div class="ps-card-footer" x-show="boot.web || overviewView==='list'">@if(\Simplify\Panel\Services\Extensions::web()) @include('server-directory::simplify.visibility') @endif<button type="button" class="ps-list-player-count" x-show="overviewView==='list'" x-on:click="s.linked && (location.href=s.url)" :disabled="!s.linked" :aria-label="s.linked?'Open '+s.name:s.name+' — not assigned to you'"><span x-text="playerCount(s)"></span><svg aria-hidden="true"><use :href="s.linked?'#ps-chevron':'#ps-lock'"/></svg></button></div><div class="ps-overview-power-wrap" x-show="overviewPreferences.showQuickActions"><div class="ps-overview-power" :class="{'is-confirming':powerConfirmation?.uuid===s.uuid}" role="group" :aria-label="'Power controls for '+(s.alias || s.name)"><template x-for="action in [{key:'start',label:'Start',icon:'play'},{key:'stop',label:'Stop',icon:'stop'},{key:'restart',label:'Restart',icon:'restart'},{key:'kill',label:'Force stop',icon:'kill'}]" :key="action.key"><button type="button" :class="{'danger':action.key==='kill'}" :title="action.label" :aria-label="action.label+' '+(s.alias || s.name)" :disabled="!!overviewPowerBusy || !canOverviewPower(s,action.key)" x-on:click.stop="overviewPower(s,action.key)"><svg aria-hidden="true"><use :href="'#ps-'+action.icon"/></svg></button></template><div class="ps-power-confirm" x-show="powerConfirmation?.uuid===s.uuid" x-cloak><button type="button" title="Cancel power action" aria-label="Cancel power action" x-on:click.stop="powerConfirmation=null"><svg><use href="#ps-kill"/></svg></button><button type="button" class="confirm" :title="'Confirm '+powerActionLabel(powerConfirmation?.action)+(powerConfirmation?.action==='kill'?' — unsaved progress may be lost':'')" :aria-label="'Confirm '+powerActionLabel(powerConfirmation?.action)" x-on:click.stop="overviewPower(s,powerConfirmation.action,true)"><svg viewBox="0 0 24 24"><path d="m5 12 4 4 10-10"/></svg></button></div></div></div></article></div></template></div><!-- Overview cards end --></div><p x-show="!boot.servers.length" class="ps-empty">No servers yet.</p></div></div><section class="ps-health-panel" x-on:click.outside="healthExpanded=false;healthOpenNodes=[]" x-show="boot.features.host_health" :class="{'expanded':healthExpanded}"><article class="ps-host-health" role="button" tabindex="0" aria-label="View health by node" :aria-expanded="healthExpanded" aria-controls="ps-health-details" x-on:click="openHostHealth()" x-on:keydown.enter.prevent="openHostHealth()" x-on:keydown.space.prevent="openHostHealth()"><div class="ps-host-state"><span class="ps-host-emblem ps-health-heart" :class="boot.host_health?.state || 'unavailable'" role="img" :aria-label="'Host health: '+(boot.host_health?.label || 'Unavailable')"><svg class="ps-host-heart" aria-hidden="true"><use href="#ps-heart"/></svg><span class="ps-host-server-badge"><svg aria-hidden="true"><use href="#ps-host"/></svg></span></span><div><div class="ps-host-heading"><h3>Host health</h3><svg class="ps-health-expand" :class="{'expanded':healthExpanded}" aria-hidden="true"><use href="#ps-chevron"/></svg></div><span class="ps-health-status" :class="boot.host_health?.state || 'unavailable'"><strong x-text="boot.host_health?.label || 'Unavailable'"></strong></span><small x-text="(boot.host_health?.available ?? 0)+' / '+(boot.host_health?.hosts ?? 0)+' hosts reporting'"></small></div></div><template x-for="metric in [{key:'cpu',label:'CPU',icon:'cpu'},{key:'memory',label:'RAM',icon:'ram'},{key:'disk',label:'Storage',icon:'disk'},{key:'network',label:'Network',icon:'traffic'}]" :key="metric.key"><div class="ps-host-metric"><div class="ps-host-heading"><svg aria-hidden="true"><use :href="'#ps-'+metric.icon"/></svg><span x-text="metric.label"></span><span class="ps-health-heart" :class="hostMetricState(metric.key)" role="img" :aria-label="metric.label+': '+hostMetricLabel(metric.key)" :title="hostMetricLabel(metric.key)"><svg aria-hidden="true"><use href="#ps-heart"/></svg></span></div><strong :class="{'ps-network-value':metric.key==='network'}" x-text="metric.key==='network'?hostRate():hostValue(metric.key)"></strong><span class="ps-card-meter" x-show="metric.key!=='network'"><span :style="{width:hostFill(metric.key)+'%'}"></span></span><small x-show="metric.key==='network'" x-text="'Used '+hostValue('network')"></small><small x-show="metric.key==='cpu' && boot.host_health?.hosts>1">Average across reporting hosts</small></div></template></article><div id="ps-health-details" class="ps-health-drawer" :inert="!healthExpanded" :aria-hidden="!healthExpanded"><div><div class="ps-health-detail-toolbar">Expand a node to view its servers</div><div class="ps-node-health-list"><template x-for="node in healthNodes()" :key="node.id"><article class="ps-node-health" :class="{'expanded':healthNodeOpen(node)}"><div class="ps-node-summary" x-on:click="if(!$event.target.closest('button'))toggleHealthNode(node)"><header><button type="button" class="ps-node-toggle" :aria-expanded="healthNodeOpen(node)" :aria-controls="'ps-node-servers-'+node.id" x-on:click="toggleHealthNode(node)"><svg class="ps-node-symbol" aria-hidden="true"><use href="#ps-host"/></svg><strong class="ps-node-name" x-text="node.name"></strong><span class="ps-health-status" :class="node.state" x-text="node.label"></span><svg class="ps-node-arrow" :class="{'expanded':healthNodeOpen(node)}" aria-hidden="true"><use href="#ps-chevron"/></svg></button></header><div class="ps-node-metrics"><template x-for="metric in [{key:'cpu',label:'CPU',icon:'cpu'},{key:'memory',label:'RAM',icon:'ram'},{key:'disk',label:'Storage',icon:'disk'},{key:'network',label:'Network',icon:'traffic'}]" :key="metric.key"><div class="ps-host-metric"><div class="ps-host-heading"><svg aria-hidden="true"><use :href="'#ps-'+metric.icon"/></svg><span x-text="metric.label"></span></div><strong :class="{'ps-network-value':metric.key==='network'}" x-text="metric.key==='network'?hostRate(node):hostValue(metric.key,node)"></strong><span class="ps-card-meter" x-show="metric.key!=='network'"><span :style="{width:hostFill(metric.key,node)+'%'}"></span></span><small x-show="metric.key==='network'" x-text="'Used '+hostValue('network',node)"></small></div></template></div></div><div class="ps-node-server-drawer" :class="{'expanded':healthNodeOpen(node)}" :id="'ps-node-servers-'+node.id" :inert="!healthNodeOpen(node)" :aria-hidden="!healthNodeOpen(node)"><div><div class="ps-node-servers"><template x-for="item in nodeServers(node)" :key="item.uuid"><div class="ps-node-server"><div><a x-show="item.linked" :href="item.url" x-text="item.alias || item.name"></a><strong x-show="!item.linked" x-text="item.alias || item.name"></strong><span class="ps-status" :class="item.status" x-text="item.status"></span></div><span><small>CPU</small><strong x-text="cpuLabel(item)"></strong></span><span><small>RAM</small><strong x-text="memoryLabel(item)"></strong></span><span><small>Storage</small><strong x-text="item.usage?.disk_bytes==null?'—':trafficBytes(item.usage.disk_bytes)"></strong></span><span><small>Network</small><strong x-text="serverRate(item)"></strong><small x-text="'Used '+serverTraffic(item)"></small></span></div></template><p x-show="!nodeServers(node).length" class="ps-help">No visible servers on this node.</p></div></div></div></article></template><p x-show="!boot.host_health?.nodes?.length" class="ps-empty">No nodes reporting yet.</p></div></div></div></section></section>
        <section x-show="server" class="ps-server-dashboard">
            <div class="ps-pending" x-show="server?.pending" x-cloak><div><strong x-text="server?.pending?.error ? 'Changes need attention' : server?.pending?.file_only ? 'File changes saved — restart to load them' : 'Stop or restart to apply changes'"></strong><small x-text="server?.pending?.error || (server?.pending?.restart_at ? 'Applying changes when the server stops. The console remains available.' : (server?.pending?.file_only ? 'Files are saved. Restart now or schedule a restart if the game needs to reload them.' : 'Your saved changes are staged until the server stops or restarts.'))"></small></div><div><button x-on:click="restartChanges(0)" :disabled="busy" class="ps-button" aria-label="Apply changes and restart" title="Restart now"><svg><use href="#ps-restart"/></svg></button><button x-on:click="open('restart')" :disabled="busy || !showWidget('restart')" class="ps-button" aria-label="Schedule restart" title="Schedule restart"><svg><use href="#ps-clock"/></svg></button><button x-on:click="discard()" :disabled="busy" class="ps-button subtle" :aria-label="server?.pending?.file_only?'Dismiss restart reminder':'Discard changes'" :title="server?.pending?.file_only?'Dismiss reminder (saved files stay changed)':'Discard changes'"><svg><use href="#ps-undo"/></svg></button></div></div>
            <article class="ps-server-heading ps-server-info" aria-label="Server information">
                <span class="ps-offline-artwork" x-show="status==='offline'" aria-label="Server offline"><svg><use href="#ps-offline"/></svg></span><img class="ps-server-banner" x-show="server?.background && status!=='offline'" :src="safeImage(server?.background)" alt="" x-on:error="$el.style.visibility='hidden'">
                <div class="ps-info-badges ps-identity-badges"><span class="ps-list-game"><svg aria-hidden="true"><use :href="server?.minecraft?'#ps-cube':'#ps-gamepad'"/></svg><span x-text="server?.minecraft?'Minecraft':(server?.software || 'Other game')"></span></span><span class="ps-status" :class="status"><i></i><span x-text="status"></span></span></div>
                <span class="ps-info-icons"><span class="ps-info-icon ps-custom-server-icon" x-show="server?.server_icon" title="server-icon.png"><img :src="safeImage(server?.server_icon)" alt="Custom server icon" x-on:load="$el.style.visibility=''" x-on:error="$el.style.visibility='hidden'"></span><span class="ps-info-icon ps-software-icon" :title="server?.pack?.modpack_name || server?.software || 'Server software'"><img x-show="server?.software_icon" :src="safeImage(server?.software_icon)" alt="Server software icon" x-on:load="$el.style.visibility=''" x-on:error="$el.style.visibility='hidden'"><svg x-show="!server?.software_icon"><use href="#ps-cube"/></svg></span></span>
                <div class="ps-info-content"><div class="ps-game-title"><h2 x-text="server?.alias || server?.name"></h2><small class="ps-real-server-name" x-show="server?.alias" x-text="'('+server?.name+')'"></small><button type="button" class="ps-icon-button subtle ps-alias-button" x-show="server?.permissions['settings.rename']" x-on:click="openAlias()" aria-label="Change alias" title="Change alias" aria-haspopup="dialog"><svg aria-hidden="true"><use href="#ps-edit"/></svg></button><div class="ps-color-control" x-on:click.outside="colorMenu=false" x-on:keydown.escape.stop="colorMenu=false">
<button type="button" class="ps-color-dot" :disabled="busy || !server?.permissions['settings.rename']" :aria-expanded="colorMenu" aria-label="Change server color" title="Server color" x-on:click="toggleColorMenu($el)"></button>
<button type="button" class="ps-background-button" :disabled="busy || !server?.permissions['settings.rename']" aria-label="Change server background" title="Server background" aria-haspopup="dialog" x-on:click="openBackground()"><svg aria-hidden="true"><use href="#ps-image"/></svg></button>
<div class="ps-color-dropdown" x-show="colorMenu" x-cloak :style="colorMenuStyle" x-on:click.stop>
<div class="ps-color-presets"><template x-for="(name,color) in (boot.available_colors || {})" :key="color"><button type="button" :style="{'background-color':color}" :title="name" :aria-label="'Select '+name+' server color'" :aria-pressed="colorDraft===color" :disabled="busy" x-on:click="colorDraft=color"></button></template></div>
<label class="ps-custom-color"><span>Custom color</span><input type="color" x-model="colorDraft" :disabled="busy" aria-label="Choose custom server color"></label>
